import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadKeshopurMianiData(){const e=readFileSync(resolve(__dirname,"../../frontend/keshopur-miani-wetland-explorer/keshopur-miani-data.js"),"utf-8");return new Function(e+"\nreturn { KESHOPUR_MIANI_INFO, ECOLOGY_HYDROLOGY, BIRD_SPECIES, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadWetlandsLandingData(){let e=readFileSync(resolve(__dirname,"../../frontend/wetlands/wetlands-data.js"),"utf-8");e=e.replace(/export\s+const\s+/g,"const ");return new Function(e+"\nreturn WETLANDS_DATA;")()}describe("Keshopur-Miani Wetland Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadKeshopurMianiData()}),describe("KESHOPUR_MIANI_INFO metadata",()=>{it("contains correct wetland metadata and status",()=>{expect(e.KESHOPUR_MIANI_INFO.id).toBe("keshopur-miani-wetland"),expect(e.KESHOPUR_MIANI_INFO.name).toContain("Keshopur-Miani"),expect(e.KESHOPUR_MIANI_INFO.ramsarYear).toBe(2019),expect(e.KESHOPUR_MIANI_INFO.ramsarSiteNo).toBe(2408),expect(e.KESHOPUR_MIANI_INFO.state).toBe("Punjab")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.KESHOPUR_MIANI_INFO.quickStats)).toBe(!0),expect(e.KESHOPUR_MIANI_INFO.quickStats.length).toBe(6)})}),describe("ECOLOGY_HYDROLOGY",()=>{it("contains overview, wetland ecology, community fisheries, and conservation status",()=>{expect(e.ECOLOGY_HYDROLOGY.overview).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.wetlandEcology).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.communityFisheries).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.conservationStatus).toBeDefined()})}),describe("BIRD_SPECIES catalog",()=>{it("is a non-empty array of bird species",()=>{expect(Array.isArray(e.BIRD_SPECIES)).toBe(!0),expect(e.BIRD_SPECIES.length).toBeGreaterThanOrEqual(4)}),it("includes Sarus Crane and Common Teal",()=>{const t=e.BIRD_SPECIES.find(e=>"sarus-crane"===e.id),a=e.BIRD_SPECIES.find(e=>"common-teal"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined()})}),describe("Landing Page Integration",()=>{it("is integrated in WETLANDS_DATA landing page dataset",()=>{const e=loadWetlandsLandingData().wetlands.find(e=>"keshopur-miani-wetland"===e.id);expect(e).toBeDefined(),expect(e.exploreUrl).toBe("../keshopur-miani-wetland-explorer/index.html")})})});